def load() -> pd.DataFrame:
    import pandas as pd, glob
    from datetime import datetime

    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*T*_0201/*.sp3'))

    rows = []
    epoch = None

    def parse_epoch(line: str):
        parts = line[1:].strip().split()
        if len(parts) < 6:
            return None
        y, mo, d, hh, mm = map(int, parts[:5])
        ss = float(parts[5])
        sec = int(ss)
        usec = int(round((ss - sec) * 1e6))
        if usec == 1000000:
            sec += 1
            usec = 0
        return datetime(y, mo, d, hh, mm, sec, usec)

    def parse_field(s):
        try:
            v = float(s)
            if abs(v) > 9e5:
                return None
            return v
        except:
            return None

    for fp in files:
        # load entire file as one-column text table
        try:
            lines = pd.read_fwf(fp, header=None, widths=[200], dtype=str)[0].tolist()
        except Exception:
            lines = pd.read_csv(fp, header=None, sep='\n', engine='python', dtype=str)[0].tolist()

        for line in lines:
            if not isinstance(line, str) or not line:
                continue
            if line.startswith('*'):
                epoch = parse_epoch(line)
                continue
            if line.startswith('P') and epoch is not None:
                sat = line[1:4].strip()
                if sat != 'A':
                    continue
                x = parse_field(line[4:18])
                y = parse_field(line[18:32])
                z = parse_field(line[32:46])
                if x is None or y is None or z is None:
                    continue
                rows.append((epoch, x, y, z))

    df = pd.DataFrame(rows, columns=['epoch', 'x_km', 'y_km', 'z_km'])
    if df.empty:
        return df

    df['epoch'] = pd.to_datetime(df['epoch'], utc=True)
    df = df.sort_values('epoch')
    df = df[(df['epoch'] >= pd.Timestamp('2019-09-02', tz='UTC')) & (df['epoch'] < pd.Timestamp('2019-09-30', tz='UTC'))]
    return df.reset_index(drop=True)

