def load() -> pd.DataFrame:
    import glob
    import pandas as pd
    from datetime import datetime

    # SP3 precise orbit files for Sept 2-29, 2019 (folders exist as seen in workflow)
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909??T??????_201909??T??????_0201/*.sp3'))
    rows = []
    cur_epoch = None

    def parse_epoch(line: str):
        # Example: "*  2019 09 02 23 59 42.00000000"
        parts = line.strip().split()
        if len(parts) < 7:
            return None
        y, mo, d, hh, mm = map(int, parts[1:6])
        sec = float(parts[6])
        isec = int(sec)
        micro = int(round((sec - isec) * 1e6))
        return datetime(y, mo, d, hh, mm, isec, micro)

    for fp in files:
        with open(fp, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    cur_epoch = parse_epoch(line)
                elif line.startswith('P') and cur_epoch is not None:
                    # Satellite id is character at index 1
                    # For Swarm-A in these files, expect 'A' => line starts with 'PA'
                    if len(line) >= 2 and line[1] == 'A':
                        # SP3 position columns are fixed width, but whitespace split works for numeric fields
                        # Fields: P{sat} X Y Z clock ...; positions are in km
                        parts = line.split()
                        if len(parts) >= 4:
                            try:
                                x = float(parts[1])
                                y = float(parts[2])
                                z = float(parts[3])
                            except Exception:
                                continue
                            rows.append((cur_epoch, x, y, z))

    df = pd.DataFrame(rows, columns=['epoch_utc', 'x_km', 'y_km', 'z_km'])
    if df.empty:
        return df

    df['epoch_utc'] = pd.to_datetime(df['epoch_utc'], utc=True)
    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')
    df = df[(df['epoch_utc'] >= start) & (df['epoch_utc'] < end)].sort_values('epoch_utc').reset_index(drop=True)
    return df

