                    # *  yyyy mm dd hh mm ss.ssssssss
                    parts = line.strip().split()
                    if len(parts) >= 7:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        sec = float(parts[6])
                        isec = int(sec)
                        usec = int(round((sec - isec) * 1e6))
                        t = datetime(y, mo, d, hh, mm, isec, usec)
                elif line.startswith('P') and t is not None:
                    # P{sat} x y z clock ... ; in km for SP3
                    sat = line[1:4].strip()
                    if sat == 'A':
                        # fixed width columns per SP3: x(4:18) y(18:32) z(32:46)
                        try:
                            x = float(line[4:18])
                            y = float(line[18:32])
                            z = float(line[32:46])
