                        rows.append({'epoch_utc': t, 'x_km': x, 'y_km': y, 'z_km': z, 'file': fp})

    df = pd.DataFrame(rows)
    if df.empty:
        return df

    df = df.sort_values('epoch_utc')
    start = pd.Timestamp('2019-09-02T00:00:00')
    end = pd.Timestamp('2019-09-30T00:00:00')
    df = df[(df['epoch_utc'] >= start) & (df['epoch_utc'] < end)]
    return df.reset_index(drop=True)

def process(sp3_list_sept) -> pd.DataFrame:
    import pandas as pd, numpy as np
    import glob
    from datetime import datetime

    # Collect September 2019 SP3 files (those exist per sp3_list_sept)
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3'))
    if len(files) == 0:
        files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))

    rows = []
    cur_t = None

    for fp in files:
        # pandas can read text without using open()
        try:
            s = pd.read_csv(fp, header=None, sep='\n', engine='python', dtype=str, on_bad_lines='skip')[0]
        except Exception:
            # fallback: read as a single column with default delimiter
            try:
                s = pd.read_csv(fp, header=None, engine='python', dtype=str, on_bad_lines='skip')[0]
            except Exception:
                continue

        for line in s.tolist():
            if not isinstance(line, str) or len(line) == 0:
                continue
            if line.startswith('*'):
                parts = line.strip().split()
                if len(parts) >= 7:
                    try:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        ss = float(parts[6])
                        sec = int(ss)
                        micro = int(round((ss - sec) * 1e6))
                        cur_t = datetime(y, mo, d, hh, mm, sec, micro)
                    except Exception:
                        cur_t = None
                else:
                    cur_t = None
            elif cur_t is not None and line.startswith('P'):
                sv = line[1:4]
                if sv != 'L47':
                    continue
                try:
                    x = float(line[4:18])
                    y = float(line[18:32])
                    z = float(line[32:46])
                except Exception:
                    continue
                rows.append((cur_t, x, y, z))

    df = pd.DataFrame(rows, columns=['epoch_utc', 'x_km', 'y_km', 'z_km'])
    if len(df) == 0:
        return df

    df = df.sort_values('epoch_utc')
    ts = pd.to_datetime(df['epoch_utc'], utc=True)
    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')
    m = (ts >= start) & (ts < end)
    out = df.loc[m].copy()
    out['epoch_utc'] = ts.loc[m].dt.tz_convert(None)
    return out.reset_index(drop=True)

