def load() -> pd.DataFrame:
    import pandas as pd, glob, re
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))
    if not files:
        files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3'))
    # filter 20190902..20190929 by folder/file name
    keep=[]
    for fp in files:
        m=re.search(r'__201909(\d\d)T', fp)
        if m:
            day=int(m.group(1))
            if 2 <= day <= 29:
                keep.append(fp)
    return pd.DataFrame({'path':keep})
